import { adjustNumberDecimals } from './adjust-number-decimals.js';
import { ExponentialDecimalLevels } from '../units.js';

/**
 * Abbreviates a number larger than/equal than the base (kilo) value provided by the
 * levels property and shifts the fraction to the left.
 * 10^x with quantifiers like K, M, B, T.
 */
export function abbreviateNumber<T>(
  /**
   * Source number to be transformed.
   * Should be in the smallest unit (as a 10^1 base value).
   */
  sourceValue: number,
  /**
   * Scale on which the numbers will be abbreviated on.
   * Defaults to ExponentialDecimalLevels:
   * - 1_000 = 1K
   * - 1_000_0000 = 1M
   */
  scale: Array<{
    multiplier: number;
    postfix: T | string;
  }> = ExponentialDecimalLevels,

  /** The amount of fraction digits to be used, if provided. */
  precision?: number,
): { formattedValue: string; postfix: string } {
  let value = Math.abs(sourceValue);
  let postfix: T | string = '';

  const level = scale
    // Sort the array first, to make sure that the find command will end
    // at the correct one
    .sort((a, b) => b.multiplier - a.multiplier)
    // Find the correct value of the abbreviation
    .find((m) => m.multiplier <= value);

  // If a level has been found, adjust the calculated value accordingly
  // and set the postfix.
  if (level !== undefined) {
    value = sourceValue / level.multiplier;
    postfix = level.postfix;
  }

  // Run the value through the precision adjustment algorithm
  // to adjust the fractionDigits within the value.
  return {
    formattedValue: adjustNumberDecimals(value, precision),
    postfix: `${postfix}`,
  };
}
